function gamepad(now){const gp=navigator.getGamepads?.()?.find(g=>g?.connected);if(!gp){lastPad=[];return;}const btn=i=>!!gp.buttons[i]?.pressed,edge=i=>btn(i)&&!lastPad[i];const modal=document.querySelector('dialog[open]'),menu=modal||(!$('overlay').hidden?$('overlay'):document.activeElement?.closest?.('#inspection'));if(edge(9)){if(modal)closeDialogs();else settings();}if(menu){const bs=[...menu.querySelectorAll('button:not([disabled]),a,input,select')].filter(b=>!b.hidden);let index=bs.indexOf(document.activeElement);if(edge(13)||edge(15)||edge(12)||edge(14)){index=(index+(edge(13)||edge(15)?1:-1)+bs.length)%Math.max(1,bs.length);bs[index]?.focus();}if(edge(0))document.activeElement?.click();if(edge(1))closeDialogs();}else if(state.status==='playing'){hover=hover||{row:2,col:1};if(now>padRepeat){let changed=false;if(btn(12)||gp.axes[1]<-.5){hover.row=Math.max(0,hover.row-1);changed=true;}if(btn(13)||gp.axes[1]>.5){hover.row=Math.min(4,hover.row+1);changed=true;}if(btn(14)||gp.axes[0]<-.5){hover.col=Math.max(0,hover.col-1);changed=true;}if(btn(15)||gp.axes[0]>.5){hover.col=Math.min(8,hover.col+1);changed=true;}if(changed)padRepeat=now+170;}if(edge(0))act(hover);if(edge(2)){E.collectAll(state);events();hud();}if(edge(1))select('shovel');if(edge(3))doUpgrade();if(edge(4)||edge(5)){let i=state.deck.indexOf(selected);select(state.deck[(i+(edge(5)?1:-1)+state.deck.length)%state.deck.length]);}}lastPad=gp.buttons.map(b=>b.pressed);}
function doUpgrade(choice){if(inspect===null&&hover)inspect=E.plantAt(state,hover.row,hover.col)?.id??null;if(inspect===null)return;if(!['a','b'].includes(choice)){if(inspect===null&&hover)inspect=E.plantAt(state,hover.row,hover.col)?.id??null;const p=state.plants.find(p=>p.id===inspect);if(!p)return;updateInspection();$('inspection').querySelector('[data-bloom]')?.focus();return;}const plant=state.plants.find(p=>p.id===inspect),cost=plant?E.upgradeCost(plant):0,r=E.upgrade(state,inspect,choice);if(!r.ok)errorToast(r.error,cost);else announce(U.lang==='zh'?'开花成功':'Bloom complete');events();hud();save();}
function pos(e){const rect=canvas.getBoundingClientRect();return {x:(e.clientX-rect.left)*1000/rect.width,y:(e.clientY-rect.top)*620/rect.height};}
function tile(p){const row=Math.floor((p.y-E.GRID.y)/E.GRID.h),col=Math.floor((p.x-E.GRID.x)/E.GRID.w);return row>=0&&row<5&&col>=0&&col<9?{row,col}:null;}
function act(cell){if(state.status!=='playing'||!cell)return;if(selected==='shovel'){const reason=E.canRemove(state,cell.row,cell.col);if(reason)errorToast(reason,50);else if(E.remove(state,cell.row,cell.col)){announce(U.lang==='zh'?'已清理第 '+(cell.row+1)+' 路，第 '+(cell.col+1)+' 格':'Cleared lane '+(cell.row+1)+', tile '+(cell.col+1));}inspect=null;}else{const p=E.plantAt(state,cell.row,cell.col);if(p)inspect=p.id;else{inspect=null;const r=E.place(state,selected,cell.row,cell.col);if(!r.ok)errorToast(r.error);else announce((U.lang==='zh'?'已种下 ':'Planted ')+t(E.PLANTS[selected].name));}}events();hud();save();}
let tap=null,longPress=false,longPressTimer;
function cancelTap(){clearTimeout(longPressTimer);tap=null;}
canvas.addEventListener('pointermove',e=>{hover=tile(pos(e));if(tap&&e.pointerId===tap.id&&Math.hypot(e.clientX-tap.x,e.clientY-tap.y)>10)cancelTap();});
canvas.addEventListener('pointerleave',()=>{hover=null;cancelTap();});
canvas.addEventListener('pointerdown',e=>{
 if(!e.isPrimary||(e.button!==undefined&&e.button!==0)||state.status!=='playing'||document.querySelector('dialog[open]')){cancelTap();return;}
 tap={x:e.clientX,y:e.clientY,id:e.pointerId};longPress=false;clearTimeout(longPressTimer);
 longPressTimer=setTimeout(()=>{if(tap){longPress=true;hover=tile(pos(e));const p=hover&&E.plantAt(state,hover.row,hover.col);if(p){inspect=p.id;updateInspection();announce(U.lang==='zh'?'已打开植物详情，战场暂停':'Plant details open. Garden on hold.');}}},420);
 canvas.focus({preventScroll:true});unlockAudio();
});
