canvas.addEventListener('pointerup',e=>{
 const start=tap;cancelTap();if(longPress||!start||e.pointerId!==start.id||Math.hypot(e.clientX-start.x,e.clientY-start.y)>10||state.status!=='playing'||document.querySelector('dialog[open]'))return;
 const p=pos(e),sun=state.energyTokens.slice().reverse().find(v=>Math.hypot(v.x-p.x,v.y-p.y)<32);
 if(sun){E.collect(state,sun.id);events();hud();return;}
 // A visible plant owns its cell even if an enemy overlaps it. Its upgrade action stays reachable.
 const cell=tile(p),plant=cell&&E.plantAt(state,cell.row,cell.col);
 if(plant){act(cell);return;}
 const enemy=state.enemies.filter(v=>!v.underground&&E.isLit(state,v.x,v.y)&&Math.abs(v.x-p.x)<26&&Math.abs(v.y-18-p.y)<43).sort((a,b)=>a.x-b.x)[0];
 if(enemy&&selected!=='shovel'){E.setFocus(state,enemy.id);toast(u('focused'));hud();return;}act(cell);
});

function downloadCard(){const c=document.createElement('canvas');c.width=1200;c.height=630;const x=c.getContext('2d'),pal=A.PALETTES[state.level.theme]||A.PALETTES.emerald;x.fillStyle=pal.shadow;x.fillRect(0,0,1200,630);x.fillStyle=pal.lawn;x.beginPath();x.ellipse(960,660,580,390,0,0,Math.PI*2);x.fill();x.fillStyle=A.ACCESSIBLE.paper;x.font='600 24px sans-serif';x.fillText('SPROUT PATROL',72,84);x.font='500 58px sans-serif';x.fillText(U.lang==='zh'?'今日院子里的战绩':'A day in the garden',72,192);x.font='32px sans-serif';x.fillText(state.level.id+' · '+t(state.level.name),72,255);x.font='600 44px sans-serif';x.fillText('★'.repeat(E.stars(state))+'☆'.repeat(3-E.stars(state)),72,350);x.font='26px sans-serif';x.fillText(Math.round(state.time)+'s · '+state.completedWaves+' '+u('wavesCompleted')+' · '+t(E.DIFFICULTIES[state.difficulty].name),72,420);x.font='21px sans-serif';x.fillText((location.host+new URL('./',location.href).pathname),72,560);const portrait=document.createElement('canvas');portrait.width=260;portrait.height=260;A.portrait(portrait.getContext('2d'),'sunbud','plant',{width:260,height:260,stage:'flower',branch:'b'});x.drawImage(portrait,860,245);c.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sprout-'+state.level.id+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');}
