function firstTip(heading,text){$('first-tip').innerHTML='<b>'+esc(heading)+'</b><span>'+esc(text)+'</span>';$('first-tip').hidden=false;firstUntil=performance.now()+3000;}
function addEffect(ev,duration){const fx=pool.pop()||effects.shift()||{};for(const k of Object.keys(fx))delete fx[k];Object.assign(fx,ev,{life:duration,max:duration});effects.push(fx);}
function events(){for(const ev of E.drainEvents(state)){Audio.event(['biteWindup','bite'].includes(ev.type)?{...ev,type:'hit'}:ev,state);if(['plant','upgrade','collect','remove'].includes(ev.type))feedback();if(ev.type==='damage'&&performance.now()-lastImpact>220){lastImpact=performance.now();hitStopUntil=lastImpact+45;}if(ev.type==='tactic'){feedback();addEffect(ev,.85);}if(ev.type==='bossEntrance'){bossUntil=performance.now()+1700;}if(['presence','warning'].includes(ev.type))soundDirection={row:ev.row??2,life:2,type:ev.enemyType};if(ev.type==='tutorial'&&ev.step===7){$('tutorial-tip').hidden=true;toast(u('tutorialComplete'));announce(u('tutorialComplete'));}if(ev.type==='draft'){overlay();save();}if(ev.type==='encounter'){E.recordEncounter(progress,state,ev.enemyType);U.saveProgress(progress);continue;}if(ev.type==='plant'&&!progress.seenTips.includes(ev.plantType)){progress.seenTips.push(ev.plantType);firstTip(u('firstPlant')+' · '+t(E.PLANTS[ev.plantType].name),t(E.PLANTS[ev.plantType].weakness));U.saveProgress(progress);}if(ev.type==='newEnemy')firstTip(u('firstEnemy')+' · '+t(E.ENEMIES[ev.enemyType].name),t(E.ENEMIES[ev.enemyType].question));
const duration=ev.type==='biteWindup'?.65:ev.type==='bite'?.28:ev.type==='sweep'?1.5:ev.type==='plantLost'?.6:ev.type==='damage'?.65:ev.type==='kill'?.8:ev.type==='collect'?.75:ev.type==='boom'?.6:ev.type==='chain'?.3:.4;if(['biteWindup','bite','plant','remove','kill','hit','collect','boom','sweep','heal','beam','upgrade','summon','push','bind','chain','grown','combo','damage','shield','portal','bond','plantLost'].includes(ev.type))addEffect(ev,duration);
if(['wave','flag','clear','sweep','enrage'].includes(ev.type)){const message=ev.type==='flag'?u('flag')+' 3s':ev.type==='clear'?(U.lang==='zh'?'喘口气 · +':'A little breathing room · +')+Math.round(25*E.DIFFICULTIES[state.difficulty].sun)+' '+u('sun'):u(ev.type==='wave'?(ev.wave===state.totalWaves?'finalWave':'incoming'):ev.type);$('wave-banner').textContent=message;$('wave-banner').hidden=false;bannerUntil=performance.now()+(ev.type==='flag'?3000:2000);announce(message);}
if(ev.type==='win'||ev.type==='loss'){if(ev.type==='loss')failureUntil=performance.now()+3000;GardenGhost.remember(state);settlement=E.settle(progress,state);reward=settlement?.reward||null;save();announce(u(ev.type==='win'?'won':'lost'));overlay();if(ev.type==='loss'&&progress.failStreak>=3&&progress.failStreak%3===0&&state.mode==='adventure')$('assist-dialog').showModal();}}
while(effects.length>140)pool.push(effects.shift());}
function tutorialArt(){if(!state.tutorial||state.tutorial.done||state.status!=='playing')return;const step=state.tutorial.step;ctx.save();ctx.strokeStyle=A.ACCESSIBLE.focus;ctx.lineWidth=4;ctx.shadowColor=A.ACCESSIBLE.focus;ctx.shadowBlur=14;if(step===0){const sun=state.energyTokens[0];if(sun){ctx.beginPath();ctx.arc(sun.x,sun.y,35,0,Math.PI*2);ctx.stroke();}}if(step===2){const c=E.center(2,0);ctx.strokeRect(c.x-41,c.y-39,82,78);}if(step===3)for(const col of [1,2]){const c=E.center(2,col);if(!E.plantAt(state,2,col))ctx.strokeRect(c.x-41,c.y-39,82,78);}if(step===6){const p=state.plants.find(v=>v.practice);if(p)ctx.strokeRect(p.x-41,p.y-39,82,78);}ctx.restore();}
function frame(now){const frameStart=performance.now();gamepad(now);const dt=Math.min(.05,last?(now-last)/1000:0);last=now;if(countdown>0&&!document.hidden){const left=3-(now-countStart)/1000;if(left<=0){countdown=0;$('resume-count').hidden=true;beginPlay();}else $('resume-count').textContent=u('restoreCount')+' '+Math.ceil(left);}
if(state.status==='playing'&&!titleScreen&&!inspectionDialog.open&&!document.querySelector('dialog[open]')&&!document.hidden&&now>=hitStopUntil){for(let i=0;i<prefs.speed;i++)E.update(state,dt);events();if(now-lastHistory>100){lastHistory=now;history.push({level:state.level,plants:state.plants.map(p=>({...p})),enemies:state.enemies.map(e=>({...e})),bullets:state.bullets.map(b=>({...b})),energyTokens:state.energyTokens.map(t=>({...t})),...Object.fromEntries(['mode','status','time','wave','guards','obstacles','failedRow','darkPulse','focus','terrainPhase','bonds','tutorial','perks'].map(k=>[k,state[k]]))});if(history.length>30)history.shift();}saveTime+=dt;if(saveTime>2){saveTime=0;save();}}
for(let i=effects.length-1;i>=0;i--){effects[i].life-=dt*prefs.speed;if(effects[i].life<=0)pool.push(effects.splice(i,1)[0]);}if(soundDirection){soundDirection.life-=dt;if(soundDirection.life<=0)soundDirection=null;}if(state.status==='lost'&&failureUntil&&now>=failureUntil){failureUntil=0;overlay();}if(now>bannerUntil)$('wave-banner').hidden=true;if(now>firstUntil)$('first-tip').hidden=true;let displayState=state;if(state.status==='lost'&&failureUntil&&history.length){const fraction=1-(failureUntil-now)/3000,frames=history.slice(-10);displayState={...state,...frames[Math.min(frames.length-1,Math.floor(fraction*frames.length))],status:'lost',failedRow:state.failedRow};}document.documentElement.dataset.world=state.level.theme;A.scene(ctx,displayState,{selected,hover,inspect,effects,reduced,noShake:prefs.noShake,performanceTier,hitStop:now<hitStopUntil,soundDirection,cameraBoss:now<bossUntil?{strength:(bossUntil-now)/1700}:0,failZoom:state.status==='lost'&&!prefs.noShake&&!reduced?1:0});if(ghost){ghost.advance(state.ticks);GardenGhost.paint(ctx,ghost,state);}if(state.status==='ready'||titleScreen)globalThis.GardenHome?.border(ctx,progress);tutorialArt();Audio.update(state);hudTime+=dt;if(hudTime>.1){hudTime=0;hud();}frameCost.push(performance.now()-frameStart);if(frameCost.length>120){const slow=frameCost.filter(n=>n>18).length;if(slow>24)performanceTier='low';frameCost=[];}requestAnimationFrame(frame);}
function changeDifficulty(value){if(!E.DIFFICULTIES[value]||value===prefs.difficulty)return;prefs.difficulty=value;if(value!=='casual')prefs.auto=false;U.savePrefs(prefs);Audio.set(prefs);closeDialogs();resetBattle(undefined,false,true);}
$('difficulty-setting').onchange=()=>changeDifficulty($('difficulty-setting').value);
for(const [id,key]of [['sound-volume','soundVolume'],['music-volume','musicVolume']])$(id).oninput=()=>{prefs[key]=Number($(id).value);U.savePrefs(prefs);unlockAudio();Audio.set(prefs);};$('font-setting').onchange=()=>{prefs.fontScale=Number($('font-setting').value);U.savePrefs(prefs);};$('shake-setting').onchange=()=>{prefs.noShake=$('shake-setting').checked;U.savePrefs(prefs);};$('auto-setting').onchange=()=>{prefs.auto=$('auto-setting').checked&&prefs.difficulty==='casual';E.setAuto(state,prefs.auto);U.savePrefs(prefs);};
function setSpeed(){prefs.speed=prefs.speed===1?2:1;U.savePrefs(prefs);hud();}
$('pause').onclick=pause;$('menu').onclick=settings;$('shovel').onclick=()=>{unlockAudio();select(selected==='shovel'?state.deck[0]:'shovel');};$('collect').onclick=()=>{unlockAudio();E.collectAll(state);events();hud();};$('speed').onclick=setSpeed;$('settings-speed').onclick=setSpeed;
$('settings-resume').onclick=()=>{$('settings-dialog').close();play();};$('restart-level').onclick=()=>{closeDialogs();resetBattle(state.deck,true,true);};$('back-title').onclick=()=>{closeDialogs();titleScreen=true;overlay();};
function fitFullscreen(){if(!document.body.classList.contains('game-fullscreen'))return;const r=$('garden').parentElement.getBoundingClientRect(),width=Math.max(1,Math.min(r.width,r.height*1000/620));canvas.style.width=width+'px';canvas.style.height=width*620/1000+'px';}
function fullscreenView(on){if(on)for(const dialog of document.querySelectorAll('dialog'))$('playfield').appendChild(dialog);document.body.classList.toggle('game-fullscreen',on);const label=U.lang==='zh'?(on?'退出全屏':'全屏'):(on?'Exit full screen':'Full screen');$('fullscreen').setAttribute('aria-label',label);$('fullscreen').setAttribute('title',label);$('fullscreen').setAttribute('aria-pressed',String(on));if(on){requestAnimationFrame(fitFullscreen);canvas.focus({preventScroll:true});}else{canvas.style.removeProperty('width');canvas.style.removeProperty('height');}}
async function exitGameFullscreen(){if(document.fullscreenElement)try{await document.exitFullscreen();}catch{}fullscreenView(false);}
$('fullscreen').onclick=async()=>{if(document.body.classList.contains('game-fullscreen')){await exitGameFullscreen();return;}fullscreenView(true);if($('playfield').requestFullscreen)try{await $('playfield').requestFullscreen();}catch{/* The fitted viewport remains available when native fullscreen is unsupported. */}};
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)fullscreenView(false);else fullscreenView(true);});window.addEventListener('resize',()=>requestAnimationFrame(fitFullscreen));window.addEventListener('gardenlanguage',()=>fullscreenView(document.body.classList.contains('game-fullscreen')));if('ResizeObserver' in window)new ResizeObserver(fitFullscreen).observe(canvas.parentElement);

for(const id of ['settings','squad','save','feedback','reset','assist'])$('close-'+id).onclick=()=>$ (id+'-dialog').close();
function feedbackData(){return 'Sprout Patrol '+E.VERSION+'\nLevel: '+state.level.id+'\nMode: '+state.mode+'\nDifficulty: '+state.difficulty+'\nNote: '+$('feedback-note').value+'\nSave: '+E.exportCode(progress,state);}
$('feedback-open').onclick=()=>{$('feedback-data').value=feedbackData();$('feedback-dialog').showModal();};$('feedback-note').oninput=()=>$('feedback-data').value=feedbackData();$('copy-feedback').onclick=async()=>toast(await U.copy(feedbackData())?u('copied'):u('copyFail'));
function saveTools(){$('save-code').value=E.exportCode(progress,state);$('import-code').value='';const list=U.backups();$('backup-list').innerHTML=list.map((b,i)=>'<button class="button" data-backup="'+i+'">'+esc(b.date.slice(0,19).replace('T',' '))+' · '+esc(b.version)+'</button>').join('');for(const b of $('backup-list').querySelectorAll('[data-backup]'))b.onclick=()=>{$('import-code').value=list[Number(b.dataset.backup)].code;};$('save-dialog').showModal();}
$('save-open').onclick=saveTools;$('copy-save').onclick=async()=>toast(await U.copy($('save-code').value)?u('saveCopied'):u('copyFail'));
$('import-save').onclick=()=>{const result=E.importCode($('import-code').value);if(!result.ok){toast(u('importBad'));return;}U.backup(progress,state);abandon();progress=result.progress;U.saveProgress(progress);U.clearBattle();state=result.battle||E.create(E.currentLevel(progress.cleared),611,undefined,progress.cleared,{meta:progress.meta,difficulty:prefs.difficulty,auto:prefs.auto,earned:progress.earned,encountered:progress.encountered});clearBattlePresentation();selected=state.deck[0];prefs.difficulty=state.difficulty;U.savePrefs(prefs);effects=[];inspect=null;reward=null;settlement=null;titleScreen=false;returnPause=state.status==='paused';closeDialogs();cards();overlay();hud();save();toast(u('importOk'));};
$('export-metrics').onclick=()=>U.download('sprout-play-records-'+U.dailyDate()+'.json',JSON.stringify(U.metrics(progress),null,2));
// Reset remains a secondary action and has two explicit confirmations plus a recoverable backup.
const resetButton=document.createElement('button');resetButton.className='text-link danger';resetButton.textContent=u('newAdventure');resetButton.id='reset-open';$('settings-dialog').appendChild(resetButton);resetButton.onclick=()=>{resetPhase=0;$('reset-title').textContent=u('restartQuestion');$('reset-body').textContent=u('restartBody');$('confirm-reset').textContent=u('backupFirst');$('reset-dialog').showModal();};$('cancel-reset').onclick=()=>$('reset-dialog').close();$('confirm-reset').onclick=()=>{if(resetPhase===0){U.backup(progress,state);resetPhase=1;$('reset-title').textContent=u('finalReset');$('reset-body').textContent=u('resetAgain')+' '+u('resetHint');$('confirm-reset').textContent=u('confirmReset');return;}abandon();progress=E.freshProgress();U.saveProgress(progress);U.clearBattle();closeDialogs();resetBattle(undefined,false,false);};
$('assist-cancel').onclick=()=>$('assist-dialog').close();$('assist-casual').onclick=()=>changeDifficulty('casual');$('assist-squad').onclick=()=>{$('assist-dialog').close();deckDraft=E.recommendedDeck(state.levelIndex,progress.cleared,progress.meta,{mode:state.mode,earned:progress.earned});openSquad();$('recommended').click();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(document.querySelector('dialog[open]'))closeDialogs();else if(inspect!==null)closeInspection();else if(document.body.classList.contains('game-fullscreen'))exitGameFullscreen();else settings();return;}if(!$('overlay').hidden||e.ctrlKey||e.metaKey||e.altKey||e.repeat||document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;const key=e.key.toLowerCase();if(key===prefs.keys.pause){e.preventDefault();pause();}else if(key===prefs.keys.harvest){E.collectAll(state);events();hud();}else if(key===prefs.keys.flower)doUpgrade();else if(key===prefs.keys.shovel)select('shovel');else{const i=state.deck.findIndex((id,n)=>key===prefs.keys['seed'+(n+1)]);if(i>=0)select(state.deck[i]);else if(e.target===canvas&&['arrowup','arrowdown','arrowleft','arrowright','enter',' '].includes(key)){e.preventDefault();hover=hover||{row:state.level.rows?.[0]??2,col:1};if(key==='arrowup')hover.row=Math.max(0,hover.row-1);if(key==='arrowdown')hover.row=Math.min(4,hover.row+1);if(key==='arrowleft')hover.col=Math.max(0,hover.col-1);if(key==='arrowright')hover.col=Math.min(8,hover.col+1);if(key==='enter'||key===' ')act(hover);else{const p=E.plantAt(state,hover.row,hover.col),reason=selected==='shovel'?E.canRemove(state,hover.row,hover.col):E.canPlant(state,selected,hover.row,hover.col);announce((U.lang==='zh'?'第 '+(hover.row+1)+' 路，第 '+(hover.col+1)+' 格':'Lane '+(hover.row+1)+', tile '+(hover.col+1))+' · '+(p?t(E.PLANTS[p.type].name):reason?u({lane:'laneError',blocked:'rockError',energy:'energyError',cooldown:'cooldownError',tutorial:'tutorialError',limit:'limitError',budget:'budgetError'}[reason]||'emptyError'):(U.lang==='zh'?'可以种植，按 Enter':'Ready to plant. Press Enter')));}}}});
window.addEventListener('gardenprefs',()=>{prefs=U.prefs();Audio.set(prefs);});
function suspend(hidden=false){if(state.status==='playing'){E.pause(state);returnPause=hidden;}if(countdown>0){countdown=0;returnPause=true;$('resume-count').hidden=true;}last=0;save();overlay();hud();Audio.update(state);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend(true);else if(returnPause&&state.status==='paused'&&!document.querySelector('dialog[open]')){overlay();hud();}});window.addEventListener('pagehide',()=>suspend(true));document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a&&!a.getAttribute('href').startsWith('#'))suspend(true);});
window.addEventListener('pageshow',()=>{last=0;const updated=U.progress();if(JSON.stringify(updated)!==JSON.stringify(progress)){progress=updated;state=U.loadBattle(progress)||makeState();clearBattlePresentation();selected=state.deck[0];inspect=null;reward=null;settlement=null;effects=[];closeDialogs();cards();overlay();hud();}else if(state.status==='paused'&&returnPause)overlay();});window.addEventListener('gardenlanguage',()=>{createConsole();cards();overlay();hud();resetButton.textContent=u('newAdventure');for(const [id,d]of Object.entries(E.DIFFICULTIES)){const option=$('difficulty-setting').querySelector('option[value="'+id+'"]');if(option)option.textContent=t(d.name);}if($('squad-dialog').open)squad();});
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;if(e.data?.type==='sprout-blind-stop'&&U.blind)suspend(false);});
window.addEventListener('gardencheckpoint',save);window.GardenPlaytest=()=>U.metrics(progress);
if(state.mode==='endless'){const retire=document.createElement('button');retire.className='button';retire.textContent=u('retire');$('settings-dialog').appendChild(retire);retire.onclick=()=>{closeDialogs();state.status='retired';settlement=E.settle(progress,state);save();overlay();};}
U.translate();cards();overlay();hud();requestAnimationFrame(frame);
